// Parcel helpers, shared by every page. Weights in kg; "≈" marks estimates. 📦
function formatWeight(kg) {
  if (kg < 1) {
    return Math.round(kg * 1000) + " g";
  }
  return kg.toFixed(1) + " kg";
}

function formatVolume(litres) {
  if (litres > 1000) {
    return (litres / 1000).toFixed(2) + " m³";
  }
  return litres + " l";
}

function statusLabel(status) {
  switch (status) {
    case "in_transit":
      return "In transit";
    case "delivered":
      return "Delivered";
    case "returned":
      return "Returned to sender";
    default:
      return "Unknown";
  }
}

const isFragile = (parcel) => parcel.tags && parcel.tags.includes("fragile");

const parcels = {
  "PX-1042": { weight: 0.4, status: "in_transit", tags: ["fragile"] },
  "PX-2077": { weight: 12.5, status: "delivered", tags: [] },
};

function trackParcel() {
  const code = document.getElementById("code").value;
  const parcel = parcels[code];
  const out = document.getElementById("result");
  if (!parcel) {
    out.textContent = "No parcel " + code;
    return;
  }
  out.textContent = statusLabel(parcel.status) + ", " + formatWeight(parcel.weight) +
    (isFragile(parcel) ? " (fragile)" : "");
}

function cancelParcel(code) {
  delete parcels[code];
  document.getElementById("result").textContent = "Cancelled " + code;
}

document.title = "Parcels (" + Object.keys(parcels).length + ")";

function submitClaim(event) {
  event.preventDefault();
  const reason = document.getElementById("reason").value;
  if (reason.length < 3) {
    document.getElementById("result").textContent = "Give a reason";
    return;
  }
  location.href = "/deliveries.html?claim=" + encodeURIComponent(reason);
}

