function listDeliveries(rows) {
  return rows
    .filter((r) => r.status === "delivered")
    .map((r) => r.code + ": " + formatWeight(r.weight));
}

function exportDeliveries() {
  return "code,weight\n";
}

document.getElementById("list").textContent = listDeliveries([
  { code: "PX-2077", status: "delivered", weight: 12.5 },
  { code: "PX-1042", status: "in_transit", weight: 0.4 },
]).join("\n");
